{"operationName":"getData","variables":{"offset":0,"limit":25},"query":"query getData($offset: Int!, $limit: Int!) {
  campaigns_aggregate(
    where: {campaign_products: {product_id: {_eq: 3206}}, deleted_at: {_is_null: true}, status: {_neq: "1"}}
    order_by: {created_at: asc}
  ) {
    aggregate {
      count
      __typename
    }
    __typename
  }
  campaigns(
    offset: $offset
    limit: $limit
    where: {campaign_products: {product_id: {_eq: 3206}}, deleted_at: {_is_null: true}, status: {_neq: "1"}}
    order_by: {created_at: asc}
  ) {
    id
    name
    campaign_products(where: {product_id: {_eq: 3206}}) {
      id
      campaign_variants_aggregate(where: {variant_id: {_in: [88624]}}) {
        aggregate {
          count
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
